#!/usr/bin/env node
/**
 * MotoAI CONTENT SITE SHELL — the ONE source of truth for every generated
 * content page (blog home, parent cluster hubs, category hubs, subtopic
 * hubs, articles, search, static pages, privacy, terms).
 *
 * Product model (v76, navigation v79):
 *   /agent/            = the Agent APP — full-screen chat (own shell,
 *                        generated by tools/agent-page.mjs, no footer).
 *   /                  = site homepage, a content page of THIS shell.
 *   every other page   = content website page that consumes THIS shell:
 *                        sticky site header (☰ Danh mục LEFT, identity,
 *                        hub nav center on desktop, search/theme/Hỏi Agent
 *                        right), the ONE sidebar (menu-drawer.mjs: a left
 *                        off-canvas panel below 1200px, an in-flow column
 *                        beside the main content from 1200px), page-ending
 *                        contact band and a real footer generated from
 *                        config/navigation.json.
 *
 * Single sources (change one, every page follows on the next build):
 *   config/blog-ui.json        site identity, feature flags, CTA, slots
 *   config/navigation.json     header, drawer and footer vocabulary
 *   data/business/*.json       NAP, hours, contact, pricing
 *   assets/css/blog.css        design tokens (color, type, space, motion)
 *   tools/blog-components.mjs  icons, brand mark, contact band, slots
 * Asset URLs carry a content hash (?v=<digits>), so editing a stylesheet or
 * script busts browser + service-worker caches on every page automatically.
 */
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { navigation, taxonomy, clusterNav, drawerCore, blogHome } from './taxonomy.mjs';
import { renderDrawer, contentLink } from './menu-drawer.mjs';
import { BLOG_UI, bannerSlot, esc, feature, icon, brandMark, contactBand, renderSlot, t } from './blog-components.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const BUSINESS = JSON.parse(readFileSync(join(ROOT, 'data/business/business.json'), 'utf8'));

import { SITE } from '../src/config/site.js';
export { SITE, esc };
/** The Agent app (full-screen chat) — every "Hỏi Agent" action points here. */
export const AGENT_URL = navigation.agent.url;

/** Build marker (page diagnostics). Cache busting no longer depends on it:
 *  every asset URL carries its own content hash (assetVersion). */
export const BUILD_VERSION = 'v76';

const versions = new Map();
/** Deterministic numeric content hash of a repo file (digits only, so the
 *  `?v=\d+` cache contract holds). Same bytes → same URL → CI-stable. */
export function assetVersion(file) {
  if (!versions.has(file)) {
    const hex = createHash('sha256').update(readFileSync(join(ROOT, file))).digest('hex');
    versions.set(file, String(parseInt(hex.slice(0, 8), 16)));
  }
  return versions.get(file);
}

/** Relative asset prefix from a page path back to repo root. */
export function rel(path) {
  const depth = path.replace(/^\/|\/$/g, '').split('/').filter(Boolean).length;
  return '../'.repeat(depth);
}

/** Saved theme + saved desktop-sidebar state are applied before first paint
 *  (no flash, no layout shift); drawer.js keeps both keys up to date. */
const NO_FLASH_THEME = `<script>/* apply saved theme + sidebar state before first paint (no flash) */(function(){try{var d=document.documentElement,t=localStorage.getItem('motoai-theme');if(t==='dark'||(t!=='light'&&window.matchMedia('(prefers-color-scheme: dark)').matches)){d.setAttribute('data-motoai-theme','dark');}if(localStorage.getItem('motoai-sidebar')==='closed'){d.setAttribute('data-motoai-sidebar','closed');}}catch(e){}})();</script>`;

/** <head> block — same meta contract as the chat homepage. `image` (an
 *  article featured image from the image registry: { url, width, height,
 *  alt }) replaces the site icon as og/twitter image and upgrades the card. */
export function pageHead({ title, description, path, ogType = 'website', headHtml = '', image = null }) {
  const url = SITE + path.replace(/^\//, '');
  const prefix = rel(path);
  const site = BLOG_UI.site;
  // Pages without their own image share the 1200×630 brand card (ogImage is the square logo).
  const og = image ? { ...image, path: null } : (site.shareImage ?? site.ogImage);
  const ogUrl = image ? image.url : `${SITE}${og.path}`;
  const css = (file) => `  <link rel="stylesheet" href="${prefix}${file}?v=${assetVersion(file)}">`;
  return `<!DOCTYPE html>
<html lang="vi" data-motion="${feature('motion') ? 'on' : 'off'}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
${headHtml}  <meta name="motoai-build" content="${BUILD_VERSION}">
  <title>${esc(title)}</title>
  <meta name="description" content="${esc(description)}">
  <link rel="canonical" href="${url}">
  <link rel="icon" href="${prefix}favicon.ico" sizes="16x16 32x32 48x48">
  <link rel="icon" href="${prefix}assets/icons/icon.svg" type="image/svg+xml">
  <meta name="theme-color" content="${site.themeColor.light}" media="(prefers-color-scheme: light)">
  <meta name="theme-color" content="${site.themeColor.dark}" media="(prefers-color-scheme: dark)">
  <meta name="color-scheme" content="light dark">
  <meta property="og:type" content="${ogType}">
  <meta property="og:site_name" content="${esc(site.name)}">
  <meta property="og:locale" content="vi_VN">
  <meta property="og:title" content="${esc(title)}">
  <meta property="og:description" content="${esc(description)}">
  <meta property="og:url" content="${url}">
  <meta property="og:image" content="${ogUrl}">
  <meta property="og:image:width" content="${og.width}">
  <meta property="og:image:height" content="${og.height}">
  <meta property="og:image:alt" content="${esc(og.alt)}">
  <meta name="twitter:card" content="${og.width >= 1200 ? 'summary_large_image' : 'summary'}">
  <meta name="twitter:title" content="${esc(title)}">
  <meta name="twitter:description" content="${esc(description)}">
  <meta name="twitter:image" content="${ogUrl}">
${css('assets/css/style.css')}
${css('assets/css/blog.css')}
  ${NO_FLASH_THEME}
</head>
<body class="content-page">
`;
}

/**
 * Desktop horizontal menu (>= 1200px) — ONE component for every page shell:
 * the content-site header renders it and so does the Agent app header
 * (tools/agent-page.mjs), so the two can never diverge. Every entry comes
 * from the drawer groups of config/navigation.json (drawerCore): the blog
 * home ("Cẩm nang"), the three parent hubs with their categories and live
 * subtopics, and the static Pages. `home` prepends Trang Chủ for a shell
 * whose brand mark is not a home link (the Agent app).
 */
export function siteNav({ activeHub = null, activeCluster = null, path = '', home = false } = {}) {
  const core = drawerCore();
  const group = (id) => core.find((e) => e.kind === 'group' && e.id === id);
  const cm = group('cm');
  const pages = group('pages');
  const blog = blogHome();
  const svg = navigation.svg_icons;
  const navIcon = (name) => icon(name, 'site-nav-icon');
  const current = (url) => (url === '/' + path ? ' aria-current="page"' : '');
  const dropdown = (parent, active, items) => '        <div class="site-nav-item"' + (active ? ' data-active="1"' : '') + '>\n' +
    '          ' + parent + '\n          <div class="site-nav-drop">\n' + items.join('\n') + '\n          </div>\n        </div>';
  const hubItems = taxonomy.clusters.map((c) => {
    const hub = cm.children.find((item) => item.kind === 'hub' && item.url === '/blog/' + c.dir + '/');
    if (!hub) throw new Error('navigation missing parent hub ' + c.id);
    const hubActive = c.dir === activeCluster ||
      hub.children.some((ch) => ch.url === '/blog/' + activeHub + '/');
    return dropdown('<a class="site-nav-parent" href="' + hub.url + '" aria-haspopup="true"' +
      (hubActive ? ' aria-current="page"' : '') + '>' + navIcon(svg.hubs[c.id]) + esc(hub.label) + icon('caret', 'site-nav-caret') + '</a>',
    hubActive, hub.children.map((ch) => '            <a class="' + (ch.level === 'subtopic' ? 'site-nav-subtopic' : 'site-nav-category') +
      '" href="' + ch.url + '"' + (ch.url === '/blog/' + activeHub + '/' ? ' aria-current="page"' : '') + '>' + esc(ch.label) + '</a>'));
  });
  const pagesItem = dropdown('<button type="button" class="site-nav-parent" aria-haspopup="true" aria-expanded="false">' +
    navIcon(svg.pages) + esc(pages.label) + icon('caret', 'site-nav-caret') + '</button>',
  pages.children.some((ch) => ch.url === '/' + path),
  pages.children.map((ch) => '            <a class="site-nav-category" href="' + ch.url + '"' + current(ch.url) + '>' + esc(ch.label) + '</a>'));
  const homeItem = home ? `          <a href="${navigation.home.url}"${current(navigation.home.url)}>${navIcon(svg.home)}${esc(navigation.home.label)}</a>\n` : '';
  return `        <nav class="site-nav" aria-label="Chuyên mục">
${homeItem}          <a href="${blog.url}"${path.startsWith('blog/') && activeCluster === null && activeHub === null ? ' aria-current="page"' : ''}>${navIcon(svg.blog)}${esc(blog.label)}</a>
${hubItems.join('\n')}
${pagesItem}
        </nav>`;
}

/**
 * The ONE menu button (v79) — the same control in the content-site header
 * and the Agent app header: ☰ + the "Danh mục" label, visible on every
 * device. Below 1200px (and always in the Agent app) it opens the sidebar
 * as a left panel; on desktop content pages it collapses/expands the
 * in-flow sidebar column (drawer.js). Labels come from config/blog-ui.json.
 */
export function menuButton() {
  return `<button type="button" class="motoai-menu" id="motoai-menu-btn" title="${esc(t('menuOpen'))}" aria-label="${esc(t('menuOpen'))}" aria-expanded="false" aria-controls="motoai-drawer" data-open="${esc(t('menuOpen'))}" data-close="${esc(t('menuClose'))}"><span class="menu-lines" aria-hidden="true"></span> <span class="motoai-menu-label">${esc(t('menuLabel'))}</span></button>`;
}

/**
 * Shared content-site header. LEFT: ☰ Danh mục (menuButton), then the
 * brand mark + MotoAI / Hỗ trợ Agent (link to the homepage). CENTER
 * (>= 1200px): siteNav(). RIGHT (.site-actions): search, theme toggle and
 * Hỏi Agent. The open/closed status is a SEPARATE flex child after
 * .site-actions (own row on mobile).
 */
function siteHeader({ activeHub, activeCluster, progress, path = '' }) {
  const site = BLOG_UI.site;
  return `    <header class="site-header">
      <div class="site-header-inner">
        ${menuButton()}
        <a class="site-brand" href="${navigation.home.url}" aria-label="${esc(site.shortName)} — trang chủ">
          <span class="site-brand-mark" aria-hidden="true">${brandMark()}</span>
          <span class="site-brand-text">
            <strong>${esc(site.shortName)}</strong>
            <span>${esc(site.tagline)}</span>
          </span>
        </a>
${siteNav({ activeHub, activeCluster, path })}
        <div class="site-actions">
          <a class="site-search-link" href="${blogHome().url}#blog-search" aria-label="Tìm bài" title="Tìm bài">${icon('search')}</a>
          <button type="button" class="blog-theme-toggle" id="blog-theme-toggle" aria-label="Chủ đề: tự động" title="Chủ đề: Auto → Sáng → Tối">Auto</button>
          <a class="site-agent-cta" href="${AGENT_URL}" aria-label="${esc(t('headerAgent'))}">${icon('chat')}<span aria-hidden="true">${esc(t('headerAgent'))}</span></a>
        </div>
        <span class="motoai-status" id="blog-business-status" role="status" aria-live="polite" hidden></span>
      </div>
${progress && feature('readingProgress') ? '      <span class="read-progress" aria-hidden="true"></span>\n' : ''}    </header>
`;
}

/**
 * The sidebar — rendered from config/navigation.json via taxonomy.drawerCore()
 * (v63, v79): the SAME order/labels/icons/links/accordion structure as the
 * Agent app's panel. Chat-only extras (divider + Xóa chat) are intentionally
 * NOT rendered here. Contact refs are resolved at runtime from business.json.
 */
function siteDrawer({ activeHub, activeCluster, path }) {
  return renderDrawer({ mode: 'content', activeHub, activeCluster, path }) + '\n';
}

/** Real site footer: brand block (mark + MotoAI · Hỗ trợ Agent + short
 *  description + ⚡ Hỏi Agent CTA), link columns from config/navigation.json
 *  (column 1 = MOTOAI, columns 2–4 = each parent hub + its child categories
 *  expanded from taxonomy.json via the "hub" field, then a secondary row for
 *  Dịch vụ + Pháp lý) and a verified business bottom bar (address + hours
 *  from data/business/business.json — never hard-coded, never 24/7). */
export function footerHtml() {
  // Columns REFERENCE drawerCore() entries (config/navigation.json
  // footer_groups): same labels, URLs and link semantics as the drawer and
  // the header, so adding a Page or hub updates every surface at once.
  const core = drawerCore();
  const group = (id) => {
    const g = core.find((e) => e.kind === 'group' && e.id === id);
    if (!g) throw new Error(`footer_groups: unknown drawer group "${id}"`);
    return g;
  };
  const top = { home: navigation.home.url, agent: navigation.agent.url };
  const resolve = (spec) => {
    if (spec.ref) return [core.find((e) => e.kind === 'link' && e.url === top[spec.ref])];
    const g = group(spec.group);
    // A group named inside a column contributes its own landing link (the
    // blog home for "Cẩm nang", labelled like the header) or its links.
    if (spec.group === 'cm') return [{ kind: 'link', ...blogHome() }];
    return g.children;
  };
  const column = (title, items, cls = '') => `      <div class="blog-footer-col${cls}">
        <p class="blog-footer-title">${esc(title)}</p>
        <ul>
${items.map((item) => `          <li>${contentLink(item, esc(item.label))}</li>`).join('\n')}
        </ul>
      </div>`;
  const primary = [];
  const secondary = [];
  for (const g of navigation.footer_groups) {
    if (g.hubs) {
      for (const c of taxonomy.clusters) {
        const hub = clusterNav(c.id);
        const kids = hub.children.map((ch) =>
          `            <li class="footer-sub"><a href="/blog/${ch.dir}/">${esc(ch.label)}</a></li>`).join('\n');
        primary.push(`      <div class="blog-footer-col is-hub">
        <p class="blog-footer-title">${esc(hub.name)}</p>
        <ul>
          <li><a class="footer-hub-link" href="${hub.url}">${esc(hub.name)}</a></li>
${kids}
        </ul>
      </div>`);
      }
    } else if (g.items) {
      primary.push(column(g.brand ? BLOG_UI.site.shortName : g.title, g.items.flatMap(resolve)));
    } else {
      (g.row === 'secondary' ? secondary : primary).push(column(group(g.group).label, group(g.group).children));
    }
  }
  const site = BLOG_UI.site;
  // Copy from config labels; NAP and hours resolve from verified business.json.
  return `    <footer class="blog-footer">
      <div class="blog-footer-inner">
        <div class="blog-footer-brand">
          <p class="blog-footer-brand-name"><span class="blog-footer-mark" aria-hidden="true">${brandMark()}</span> <strong>${esc(site.shortName)}</strong> <span class="blog-footer-agent">· ${esc(site.tagline)}</span></p>
          <p class="blog-footer-desc">${esc(t('footerDesc', {}, BUSINESS))}</p>
          <a class="blog-footer-cta" href="${AGENT_URL}">${esc(BLOG_UI.cta.footerLabel)}</a>
        </div>
        <nav class="blog-footer-nav" aria-label="Chân trang">
${primary.join('\n')}
        </nav>
      </div>
      <div class="blog-footer-secondary">
        <nav class="blog-footer-nav" aria-label="Dịch vụ và pháp lý">
${secondary.join('\n')}
        </nav>
      </div>
      <div class="blog-footer-bottom">
        <p>${esc(t('footerNap', {}, BUSINESS))}</p>
        <p>${esc(t('footerHours', {}, BUSINESS))}</p>
      </div>
    </footer>
`;
}

/** Page-ending action: opens the Agent app (/agent/) with the topic
 *  prefilled, plus verified call + one contextual action for the category
 *  (config/blog-ui.json cta). Slot `page.beforeContactBand` renders first. */
export function askAgentAction(topic, category = null) {
  return renderSlot('page.beforeContactBand', { category })
    + contactBand({ topic, category, business: BUSINESS });
}

function shellScripts({ search }) {
  const js = (file, module = false) => `  <script${module ? ' type="module"' : ''} src="/${file}?v=${assetVersion(file)}"></script>\n`;
  return (search ? js('assets/js/blog.js') : '') + js('assets/js/app-shell.js', true);
}

/**
 * Compose one full content page inside the shared content-site shell.
 * @param {object} o
 * @param {string} o.title / o.description / o.path — SEO head values
 * @param {string} o.screen — screen id (page stats)
 * @param {string} o.activeHub — active category dir (header/drawer state)
 * @param {string} o.contentHtml — the main content column
 * @param {string} o.schemaHtml — JSON-LD scripts (placed before closing body)
 * @param {boolean} o.search — include the blog search runtime (blog home only)
 */
export function appShellPage({ title, description, path, screen, activeHub = null, activeCluster = null, contentHtml, schemaHtml = '', search = false, ogType = 'website', headHtml = '', image = null }) {
  // DOM order = reading order: skip link, header, sidebar (the desktop
  // column sits left of <main>; below 1200px it is an off-canvas panel that
  // takes no part in the flow), banner, main, footer.
  return pageHead({ title, description, path, ogType, headHtml, image })
    + `  <a class="skip-link" href="#site-main">${esc(t('skipToContent'))}</a>\n`
    + siteHeader({ activeHub, activeCluster, progress: ogType === 'article', path })
    + siteDrawer({ activeHub, activeCluster, path })
    + bannerSlot(esc)
    + `  <main class="site-main" id="site-main" data-motoai-screen="${esc(screen)}">
${contentHtml}
  </main>
${footerHtml()}
${schemaHtml}
${shellScripts({ search })}</body>
</html>
`;
}
